<template>
  <div class="app-container referral-page">
    <div class="heading"><div><h2>推荐奖励</h2><p>绑定关系、达标审核、奖励发券与异常核查</p></div><el-button :disabled="busy" icon="el-icon-refresh" @click="load">刷新</el-button></div>
    <el-tabs v-model="kind" @tab-click="changeTab">
      <el-tab-pane label="绑定记录" name="bindings"/>
      <el-tab-pane name="records"><span slot="label">推荐列表 <el-badge :value="counts.pending" :hidden="!Number(counts.pending)" :max="99"/></span></el-tab-pane>
      <el-tab-pane label="发券记录" name="rewards"/>
      <el-tab-pane name="anomalies"><span slot="label">异常待处理 <el-badge :value="counts.anomalies" :hidden="!Number(counts.anomalies)" :max="99"/></span></el-tab-pane>
    </el-tabs>
    <el-form inline size="small" @submit.native.prevent>
      <el-form-item label="家长手机号"><el-input v-model.trim="query.parentPhone" placeholder="输入家长手机号，至少3位" clearable :disabled="busy" @keyup.enter.native="search"/></el-form-item>
      <el-form-item label="关系角色"><el-select v-model="query.recipientRole" :disabled="busy"><el-option label="新老用户" value=""/><el-option label="新用户（被推荐人）" value="NEW"/><el-option label="老用户（推荐人）" value="OLD"/></el-select></el-form-item>
      <el-form-item label="状态"><el-select v-model="query.state" clearable :disabled="busy"><el-option v-for="s in states" :key="s" :label="label(s)" :value="s"/></el-select></el-form-item>
      <el-form-item><el-button type="primary" :disabled="busy || loading" @click="search">查询</el-button></el-form-item>
      <el-form-item v-if="kind==='records'"><el-button type="success" :disabled="busy || !selection.length" @click="openReward">审核并发券（{{selection.length}}条）</el-button></el-form-item>
    </el-form>
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <el-table ref="records" v-loading="loading" :data="rows" :row-key="rowKey" @selection-change="selection=$event">
      <el-table-column v-if="kind==='records'" type="selection" width="48"/>
      <el-table-column type="expand"><template slot-scope="s"><div class="history"><div v-for="(e,i) in history(s.row.history)" :key="i"><strong>{{label(e.action)}}</strong> · {{e.time}} · 操作人 {{e.actorId}}<p>{{e.reason}}<span v-if="e.result"> · 处理结果：{{e.result}}</span><span v-if="e.fromReferrerId"> · 原推荐人ID：{{e.fromReferrerId}} → {{e.referrerId}}</span></p></div><span v-if="!history(s.row.history).length">来源关系 #{{s.row.bindingId}} · 推荐记录 #{{s.row.recordId}}</span></div></template></el-table-column>
      <el-table-column label="记录" width="140"><template slot-scope="s">#{{rowKey(s.row)}}<div class="muted" v-if="s.row.recordId && kind!=='records'">推荐 #{{s.row.recordId}}</div></template></el-table-column>
      <el-table-column label="新用户（被推荐人）" min-width="180"><template slot-scope="s"><strong>{{s.row.inviteeName}}</strong><div class="muted">{{s.row.inviteePhone || '未填写手机号'}}</div></template></el-table-column>
      <el-table-column label="老用户（推荐人）" min-width="180"><template slot-scope="s"><strong>{{s.row.referrerName}}</strong><div class="muted">{{s.row.referrerPhone || '未填写手机号'}}</div></template></el-table-column>
      <el-table-column label="状态" min-width="130"><template slot-scope="s"><el-tag size="small">{{label(s.row.state || s.row.recommendationStatus || s.row.reviewStatus || s.row.couponStatus)}}</el-tag><div class="warning" v-if="s.row.cause">{{label(s.row.cause)}}</div></template></el-table-column>
      <el-table-column v-if="kind==='rewards'" label="奖励来源与接收" min-width="210"><template slot-scope="s">{{s.row.couponName}} · ¥{{s.row.discountAmount}}<div class="muted">接收手机号 {{s.row.parentPhone || '未填写'}} · {{label(s.row.recipientRole)}}<br>优惠券 #{{s.row.userCouponId}} · {{label(s.row.couponStatus)}}</div></template></el-table-column>
      <el-table-column label="最近时间" min-width="170"><template slot-scope="s">{{s.row.updateTime || s.row.createTime || s.row.qualifiedAt || s.row.boundAt}}</template></el-table-column>
      <el-table-column label="操作" width="150" fixed="right"><template slot-scope="s"><el-button v-if="kind==='bindings' && !s.row.lockedAt" type="text" :disabled="busy" @click="correct(s.row)">纠错</el-button><span v-if="kind==='bindings' && s.row.lockedAt" class="muted">关系已锁定</span><el-button v-if="kind==='rewards' && s.row.couponStatus==='AVAILABLE'" type="text" :disabled="busy" @click="revoke(s.row)">撤回奖励券</el-button><el-button v-if="kind==='anomalies' && s.row.state==='OPEN'" type="text" :disabled="busy" @click="resolve(s.row)">记录处理结果</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load"/>
    <el-dialog title="审核并发放推荐奖励" :visible.sync="rewardOpen" width="680px" :close-on-click-modal="false" :close-on-press-escape="!uncertain" :before-close="closeReward">
      <el-alert title="家长人数按用户ID去重，券数量按推荐记录计算；同一记录、接收人、模板只发一次。" type="info" :closable="false"/>
      <el-form label-width="100px" class="reward-form">
        <el-form-item label="优惠券模板"><el-select v-model="templateId" :disabled="busy || uncertain" @change="resetPreview"><el-option v-for="t in templates" :key="t.templateId" :label="templateLabel(t)" :value="t.templateId"/></el-select></el-form-item>
        <el-form-item label="接收角色"><el-radio-group v-model="rewardRole" :disabled="busy || uncertain" @change="resetPreview"><el-radio label="BOTH">新老双方</el-radio><el-radio label="NEW">新用户</el-radio><el-radio label="OLD">老用户</el-radio></el-radio-group></el-form-item>
        <el-form-item label="审核原因"><el-input v-model="reason" type="textarea" maxlength="255" show-word-limit :disabled="busy || uncertain"/></el-form-item>
      </el-form>
      <div v-if="preview" class="preview"><h3>{{preview.recipientCount}}名家长 · {{preview.couponCount}}张券</h3><p>{{templateLabel(preview.template)}}</p><el-checkbox-group v-model="selectedParents" :disabled="busy || uncertain" @change="selectParents"><el-checkbox v-for="p in preview.recipients" :key="p.parentId" :label="p.parentId">{{p.parentName}}（{{p.parentPhone || '未填写手机号'}}）</el-checkbox></el-checkbox-group><el-table :data="preview.items" size="mini"><el-table-column prop="recordId" label="推荐记录"/><el-table-column prop="parentPhone" label="接收手机号"/><el-table-column label="关系角色"><template slot-scope="s">{{label(s.row.recipientRole)}}</template></el-table-column></el-table></div>
      <el-alert v-if="uncertain" title="发放结果未确认，名单已锁定。请重试原批次或查看发券记录，不要另开相同批次。" type="warning" :closable="false"/>
      <span slot="footer"><el-button :disabled="busy || uncertain" @click="closeReward">关闭</el-button><el-button v-if="!uncertain" :disabled="busy" @click="previewReward">{{preview?'更新预览':'预览接收名单'}}</el-button><el-button type="primary" :disabled="busy || (!uncertain && (!preview || !preview.previewHash))" :loading="busy" @click="grant">{{uncertain?'重试原批次':'确认发放'}}</el-button></span>
    </el-dialog>
  </div>
</template>
<script>
import { getToken } from '@/utils/auth'
import { listTemplates } from '@/api/system/coupon'
import { listReferrals,referralCounts,previewReferralReward,grantReferralReward,correctReferral,revokeReferralReward,resolveReferralAnomaly } from '@/api/system/referral'
const LABELS={WAITING:'待达标',PENDING:'待奖励审核',REWARDED:'已发奖励',OPEN:'待核查',RESOLVED:'已处理',AVAILABLE:'未使用',LOCKED:'占用中',USED:'已使用',REVOKED:'已撤回',CANCELLED:'达标报名已取消',FULL_REFUND:'达标收款已全额退款',PAYMENT_INVALID:'收款资格异常',NEW:'新用户',OLD:'老用户',BIND:'绑定',CORRECT:'纠错',GRANT:'发放奖励',REVOKE:'撤回奖励',DETECTED:'发现异常',RESOLVE:'处理异常'}
export default {
  name:'ReferralRewards',
  data(){return{kind:'records',rows:[],selection:[],total:0,loading:false,busy:false,error:'',counts:{pending:0,anomalies:0},query:{pageNum:1,pageSize:20,parentPhone:'',recipientRole:'',state:''},rewardOpen:false,templates:[],templateId:'',rewardRole:'BOTH',reason:'',preview:null,selectedParents:[],uncertain:false}},
  computed:{states(){return this.kind==='anomalies'?['OPEN','RESOLVED']:this.kind==='bindings'?['WAITING','PENDING','REWARDED']:this.kind==='records'?['PENDING','REWARDED']:[]}},
  created(){this._alive=true;this._visible=true;this._token=getToken();this.load();this._timer=setInterval(()=>this.loadCounts(),30000)},
  activated(){this._visible=true;const token=getToken();if(token!==this._token){this._token=token;this._frozen=null;this.rows=[];this.selection=[];this.counts={pending:0,anomalies:0};this.preview=null;this.rewardOpen=false;this.uncertain=false;this.busy=false;this.reason='';this.query.parentPhone=''}this.load();clearInterval(this._timer);this._timer=setInterval(()=>this.loadCounts(),30000)},
  deactivated(){this._visible=false;this._version=(this._version||0)+1;clearInterval(this._timer);if(this._frozen)this.uncertain=true;this.busy=false},
  beforeDestroy(){this._alive=false;clearInterval(this._timer);this._version=(this._version||0)+1},
  methods:{
    templateLabel(t){let subjects=t.subjectNames;try{subjects=typeof subjects==='string'?JSON.parse(subjects):subjects}catch(e){subjects=[]}return `${t.couponName} · ${Number(t.minSpendAmount)>0?'满 '+t.minSpendAmount+' 减 ':'无门槛减 '}${t.discountAmount} · ${(subjects||[]).join('、')||'不限学科'} · 有效至 ${t.validUntil}`},
    current(){return this._alive && this._visible && this._token===getToken()},label(s){return LABELS[s]||s||''},history(raw){try{return typeof raw==='string'?JSON.parse(raw):raw||[]}catch(e){return[]}},rowKey(r){return r[this.kind==='bindings'?'bindingId':this.kind==='records'?'recordId':this.kind==='rewards'?'rewardId':'anomalyId']},
    async load(){if(!this.current())return;const v=this._version=(this._version||0)+1;this.loading=true;this.error='';try{const [list,counts]=await Promise.all([listReferrals({...this.query,kind:this.kind}),referralCounts()]);if(!this.current()||v!==this._version)return;this.rows=list.rows||[];this.total=list.total||0;this.counts=counts.data;if(this.$emit)this.$emit('counts-change',this.counts);this.selection=[]}catch(e){if(this.current()&&v===this._version){this.error=e.message||'加载失败';this.rows=[];this.counts={pending:0,anomalies:0}}}finally{if(this.current()&&v===this._version)this.loading=false}},
    async loadCounts(){if(!this.current())return;const v=this._version;try{const r=await referralCounts();if(this.current()&&v===this._version){this.counts=r.data;if(this.$emit)this.$emit('counts-change',this.counts)}}catch(e){}},
    changeTab(){this.query.state='';this.query.pageNum=1;this.load()},search(){if(this.query.parentPhone&&!/^[0-9]{3,11}$/.test(this.query.parentPhone)){this.$message.error('请输入3至11位家长手机号');return}this.query.pageNum=1;this.load()},
    async openReward(){if(this.busy||!this.current()||!this.selection.length)return;this._draftIds=this.selection.map(r=>r.recordId);this.busy=true;const v=this._version;try{const r=await listTemplates({templateStatus:'ACTIVE',pageSize:100});if(this.current()&&v===this._version){this.templates=r.rows||[];this.templateId='';this.rewardRole='BOTH';this.reason='';this.preview=null;this.selectedParents=[];this._parentsPicked=false;this._frozen=null;this._key=`REF_${Date.now()}_${Math.random().toString(36).slice(2,12)}`;this.uncertain=false;this.rewardOpen=true}}catch(e){if(this.current()&&v===this._version)this.error=e.message||'模板加载失败'}finally{if(this.current()&&v===this._version)this.busy=false}},
    resetPreview(){this.preview=null;this.selectedParents=[];this._parentsPicked=false;this._frozen=null},selectParents(){this._parentsPicked=true;this.preview={...this.preview,previewHash:''}},
    draft(){return{recordIds:this._draftIds,templateId:this.templateId,recipientRole:this.rewardRole,...(this._parentsPicked?{parentIds:this.selectedParents.slice()}:{}),reason:this.reason.trim(),idempotencyKey:this._key}},
    async previewReward(){if(this.busy||this.uncertain||!this.current())return;if(!this.templateId||!this.reason.trim()){this.$message.error('请选择模板并填写审核原因');return}const v=this._version;this.busy=true;try{const r=await previewReferralReward(this.draft());if(this.current()&&v===this._version){this.preview=r.data;this.selectedParents=r.data.recipients.map(p=>p.parentId);this._parentsPicked=true;this._frozen=null}}catch(e){if(this.current()&&v===this._version){this.preview=null;this.error=e.message||'预览失败'}}finally{if(this.current()&&v===this._version)this.busy=false}},
    async grant(){if(this.busy||!this.current())return;if(!this._frozen){if(!this.preview||!this.preview.previewHash)return;this._frozen={...this.draft(),previewHash:this.preview.previewHash}}this.busy=true;const v=this._version;try{if(!this.uncertain){try{await this.$confirm(`向${this.preview.recipientCount}名家长发放${this.preview.couponCount}张「${this.preview.template.couponName}」？`,'确认推荐奖励',{type:'warning'})}catch(e){this._frozen=null;return}}if(!this.current()||v!==this._version)return;await grantReferralReward(this._frozen);if(this.current()&&v===this._version){this._frozen=null;this.uncertain=false;this.rewardOpen=false;this.$message.success('奖励已发放');this.busy=false;await this.load()}}catch(e){if(this.current()&&v===this._version){this.uncertain=!e.applicationRejected;if(!this.uncertain){this._frozen=null;this.preview=null;this._key=`REF_${Date.now()}_${Math.random().toString(36).slice(2,12)}`}this.$message.error(e.message||'结果未确认，请重试原批次')}}finally{if(this.current()&&v===this._version)this.busy=false}},
    closeReward(done){if(this.busy||this.uncertain)return;this.rewardOpen=false;this._frozen=null;if(typeof done==='function')done()},
    async correct(row){if(this.busy||!this.current())return;const v=this._version;this.busy=true;try{const c=await this.$prompt('请输入新的16位推荐码','关系纠错',{inputPattern:/^[A-Za-z0-9]{16}$/,inputErrorMessage:'请输入16位推荐码'});if(!this.current()||v!==this._version)return;const r=await this.$prompt('填写纠错原因；仅首次确认收款前可纠错','保留纠错历史',{inputPattern:/\S+/,inputErrorMessage:'请填写原因'});if(!this.current()||v!==this._version)return;await correctReferral(row.bindingId,{code:c.value,reason:r.value,version:row.version});if(this.current()&&v===this._version){this.$message.success('关系已纠正');this.busy=false;await this.load()}}catch(e){}finally{if(this.current()&&v===this._version)this.busy=false}},
    async revoke(row){if(this.busy||!this.current())return;const v=this._version;this.busy=true;try{const r=await this.$prompt('仅未使用且未占用的奖励券可撤回，请填写原因','撤回奖励',{inputPattern:/\S+/,inputErrorMessage:'请填写原因'});if(!this.current()||v!==this._version)return;await revokeReferralReward(row.rewardId,{reason:r.value});if(this.current()&&v===this._version){this.$message.success('已撤回');this.busy=false;await this.load()}}catch(e){}finally{if(this.current()&&v===this._version)this.busy=false}},
    async resolve(row){if(this.busy||!this.current())return;const v=this._version;this.busy=true;try{const a=await this.$prompt('填写核查原因','异常核查',{inputPattern:/\S+/,inputErrorMessage:'请填写原因'});if(!this.current()||v!==this._version)return;const b=await this.$prompt('填写处理结果，不自动追款或改写历史','处理结果',{inputPattern:/\S+/,inputErrorMessage:'请填写结果'});if(!this.current()||v!==this._version)return;await resolveReferralAnomaly(row.anomalyId,{reason:a.value,result:b.value});if(this.current()&&v===this._version){this.$message.success('已记录处理结果');this.busy=false;await this.load()}}catch(e){}finally{if(this.current()&&v===this._version)this.busy=false}}
  }
}
</script>
<style scoped>
.heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.heading h2{margin:0 0 8px}.heading p,.muted{color:#8793a5;font-size:12px}.warning{color:#c16b32;font-size:12px;margin-top:8px}.history{padding:12px 36px;line-height:1.8}.history p{margin:4px 0 16px}.reward-form{margin-top:24px}.reward-form .el-select{width:100%}.preview{padding:16px;background:#f5f7fb;border-radius:8px;margin:12px 0}.preview .el-checkbox{line-height:2.5}.referral-page .el-badge{margin-left:4px}
</style>
